    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    for color in {v for row in grid for v in row if v != bg}:
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr,dc in ((1,1),(1,-1)):
            diag_groups = {}
            for r,c in pts:
                key = (c-r if dc==1 else c+r)
                diag_groups.setdefault(key, []).append((r,c))
            for group in diag_groups.values():
                if len(group) < 2: continue
                group.sort()
                # Continue each established diagonal through the grid in both directions.
                r0,c0 = group[0]
                r1,c1 = group[-1]
                for sign in (-1,1):
                    r,c = (r0-dr,c0-dc) if sign==-1 else (r1+dr,c1+dc)
                    while 0 <= r < h and 0 <= c < w:
                        if out[r][c] == bg: out[r][c] = color
                        r += sign*dr; c += sign*dc
    return out
